types.cg='CG 画面';typeIcons.cg='assets';
function insertCgBlock(values={}){change(()=>{const b={id:uid(),type:'cg',asset:'',visible:true,wait:true,fit:'contain',transition:'fade',duration:700,text:'显示 CG',...values};const i=scene().blocks.findIndex(b=>b.id===selected);scene().blocks.splice(i<0?scene().blocks.length:i+1,0,b);selected=b.id;view='script';mode='visual';stopContentPlayback()});revealStoryBlock(selected)}
function openCgInsert(assetId=''){dialog('插入 CG',`<div class="field"><label>CG 图片</label><select name="asset" required data-cg-preview>${assetOptions(assetId)}</select></div><img id="cgDialogPreview" class="cg-dialog-preview" alt="CG 预览" ${assetId?'src="'+esc(asset(assetId)?.data)+'"':'hidden'}><button class="btn small" type="button" data-action="import-cg-image">导入本地图片</button><div class="field-row" style="margin-top:15px"><div class="field"><label>图片适配</label><select name="fit"><option value="contain">完整显示（保留全图）</option><option value="cover">铺满画面（可能裁切）</option></select></div><div class="field"><label>切换效果</label><select name="transition">${optionList(KotobaCore.effects,'fade')}</select></div></div><div class="field"><label>切换时长（毫秒）</label><input name="duration" type="number" min="0" max="5000" value="700"></div><label class="subtitle-check"><input name="wait" type="checkbox" checked>显示后等待点击再继续</label><p>CG 会覆盖背景和角色立绘，后续对白仍可显示。插入「隐藏 CG」后恢复场景画面。</p>`,'插入 CG',f=>insertCgBlock({asset:f.get('asset'),fit:f.get('fit'),transition:f.get('transition'),duration:KotobaCore.duration(f.get('duration')),wait:f.has('wait'),text:'显示 CG · '+asset(f.get('asset'))?.name}))}
function importCgImage(){pickFile('image/png,image/jpeg,image/webp,image/gif',file=>{if(file.size>MAX_ASSET_BYTES){notify('请选择 20 MB 内的图片');return}if(!/^image\/(png|jpeg|webp|gif)$/.test(file.type)){notify('请选择 PNG、JPEG、WebP 或 GIF 图片');return}const reader=new FileReader();reader.onload=()=>{const item={id:uid(),name:file.name,type:'image',data:reader.result};change(()=>project.assets.push(item));const select=$('[data-cg-preview]');if(select){select.innerHTML=assetOptions(item.id);$('#cgDialogPreview').src=item.data;$('#cgDialogPreview').hidden=false}notify('CG 图片已导入')};reader.onerror=()=>notify('图片读取失败，请重试');reader.readAsDataURL(file)})}
const cgDraw=draw,cgInspector=drawInspector,cgResolve=resolvePlayable;
draw=function(){cgDraw();if(view==='script')$('.block-footer')?.insertAdjacentHTML('beforeend','<button class="btn small" data-action="insert-cg">＋ CG</button><button class="btn small" data-action="hide-cg">隐藏 CG</button>');if(view==='assets')document.querySelectorAll('.asset-card').forEach(card=>{const id=card.querySelector('[data-action="use-asset"]')?.dataset.id;if(asset(id)?.type==='image')card.querySelector('.card-actions').insertAdjacentHTML('beforeend',`<button class="btn small" data-action="use-cg" data-id="${esc(id)}">用作 CG</button>`)});if(view==='script')for(const b of scene().blocks)if(b.type==='cg'){const row=Array.from(document.querySelectorAll('.block')).find(el=>el.dataset.id===b.id);if(row?.querySelector('.block-text'))row.querySelector('.block-text').textContent=b.visible===false?'隐藏 CG':'显示 CG · '+(asset(b.asset)?.name||'未选择图片')}};
drawInspector=function(){cgInspector();const b=block();if(b?.type!=='cg')return;$('#inspector').insertAdjacentHTML('afterbegin',`<div class="field"><label>CG 状态</label><select data-cg="visible"><option value="show" ${b.visible!==false?'selected':''}>显示 CG</option><option value="hide" ${b.visible===false?'selected':''}>隐藏 CG，恢复场景</option></select></div>${b.visible!==false?`<div class="field"><label>CG 图片</label><select data-edit="asset">${assetOptions(b.asset)}</select></div><div class="field"><label>图片适配</label><select data-cg="fit">${optionList({contain:'完整显示',cover:'铺满画面'},b.fit||'contain')}</select></div><label class="subtitle-check"><input type="checkbox" data-cg="wait" ${b.wait!==false?'checked':''}>显示后等待点击再继续</label>`:''}${effectFields(b,'block')}<button class="btn small" data-action="preview-effect">重播切换效果</button><p class="field-note">CG 持续覆盖当前章的背景和立绘，后续台词可显示在 CG 上。隐藏 CG 后恢复当前背景与立绘。</p>`)};
resolvePlayable=function(){let guard=0;while(!ended&&guard++<100){let b=project.scenes.find(s=>s.id===playScene)?.blocks[playIndex];if(b?.type==='cg'&&(b.visible===false||b.wait===false)){playIndex++;continue}cgResolve();b=project.scenes.find(s=>s.id===playScene)?.blocks[playIndex];if(b?.type==='cg'&&(b.visible===false||b.wait===false))continue;return}if(guard>=100){ended=true;notify('连续控制块过多，已结束试演')}};
document.addEventListener('click',e=>{const btn=e.target.closest('[data-action]'),action=btn?.dataset.action;if(!['insert-cg','hide-cg','use-cg','import-cg-image'].includes(action))return;e.preventDefault();e.stopImmediatePropagation();if(action==='insert-cg')openCgInsert();if(action==='use-cg')openCgInsert(btn.dataset.id);if(action==='hide-cg')insertCgBlock({visible:false,wait:false,text:'隐藏 CG'});if(action==='import-cg-image')importCgImage()},true);
document.addEventListener('change',e=>{const el=e.target;if(el.hasAttribute('data-cg-preview')){const a=asset(el.value);$('#cgDialogPreview').hidden=!a;if(a)$('#cgDialogPreview').src=a.data}if(el.dataset.cg)change(()=>{const b=block();if(b?.type!=='cg')return;b[el.dataset.cg]=el.dataset.cg==='visible'?el.value==='show':el.dataset.cg==='wait'?el.checked:el.value})});
const cgValidate=validateProject;
validateProject=function(p){cgValidate(p);for(const s of p.scenes)for(const b of s.blocks)if(b.type==='cg'){if(b.fit!==undefined&&!['contain','cover'].includes(b.fit))throw Error('CG 图片适配方式无效');if(b.visible!==undefined&&typeof b.visible!=='boolean'||b.wait!==undefined&&typeof b.wait!=='boolean')throw Error('CG 显示状态无效')}return p};
draw();
